"""
Tests for the X-drive forward-kinematics slip residual (pure numpy, no ROS).
"""

from __future__ import annotations

import numpy as np

from fortis_comms.xdrive_kinematics import H, xdrive_fk_residual, xdrive_fk_solver


def test_slip_free_wheel_speeds_have_zero_residual_and_round_trip():
    """Wheel speeds generated by H carry no residual and recover the twist."""
    for twist in ((0.2, 0.0, 0.0), (0.0, 0.15, 0.0), (0.0, 0.0, 0.5),
                  (0.1, -0.05, 0.3)):
        wheel_speeds = H @ np.array(twist)
        assert xdrive_fk_residual(wheel_speeds) < 1e-12
        np.testing.assert_allclose(xdrive_fk_solver(wheel_speeds), twist, atol=1e-12)


def test_one_slipping_wheel_raises_the_residual():
    """Adding 0.1 m/s to one wheel breaks FL + FR == RL + RR measurably."""
    wheel_speeds = H @ np.array((0.2, 0.0, 0.0))
    for wheel in range(4):
        slipped = wheel_speeds.copy()
        slipped[wheel] += 0.1
        assert xdrive_fk_residual(slipped) > 0.02


def test_left_null_vector_annihilates_h():
    """[1, 1, -1, -1] is in H's left null space, the identity the residual uses."""
    np.testing.assert_allclose(np.array([1, 1, -1, -1]) @ H, 0.0, atol=1e-12)
